import { render, route } from "rwsdk/router";
import { defineApp, type RequestInfo } from "rwsdk/worker";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { createDb, type Database } from "@/db/client";
import { listUsers, createUser } from "@/app/api/users";

/**
 * Per-request context. Anything stored here is available to every
 * middleware and route handler via the `ctx` argument on `RequestInfo`.
 */
export type AppContext = {
  db: Database;
};

export default defineApp([
  setCommonHeaders(),
  // Attach a Drizzle client backed by the D1 binding to the request context.
  // This middleware runs before any route handler, so handlers can rely on
  // `ctx.db` being available.
  ({ ctx, env }) => {
    ctx.db = createDb(env.DB);
  },
  route("/api/users", {
    get: (info: RequestInfo) => listUsers(info),
    post: (info: RequestInfo) => createUser(info),
  }),
  render(Document, [route("/", Home)]),
]);

